import Header from './components/Header'
import './App.css';
import background from './images/bg.jpg'
function App() {
  return (
    <div style={{backgroundColor: '#3C413E'}}>
      <div style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center', backgroundSize: 'cover', width: '70vw', height: '100vh', borderTopRightRadius: '10%',borderBottomRightRadius: '10%', opacity: 0.8}}>
        <div style={{ position: 'relative', top: 80, left: 150, fontSize: 80}}> Connect with Your co-passengers</div>
      </div>
    </div>
  )
}
export default App;
